//! The `PrimJS` reader over the generated bytecode corpus of
//! `reactlynx-test-fixtures` (`pnpm --filter reactlynx-test-fixtures build`
//! writes it): every program in every variant, both the `ROOT_LEPUS` and the
//! `JS_BYTECODE` copy, and both pages of every native `ReactLynx` fixture. Each
//! must extract, read and disassemble.

#[path = "../../../packages/reactlynx-test-fixtures/bytecode.rs"]
#[allow(
    clippy::doc_markdown,
    reason = "the registry is the fixture package's file"
)]
mod bytecode;

use std::collections::BTreeSet;

use bobcat_source::native::primjs::{
    self, ALL_OPCODES, Function, Header, Opcode, SectionKind, Value,
};

fn walk<'a>(function: &'a Function, out: &mut Vec<&'a Function>) {
    out.push(function);
    for value in &function.cpool {
        if let Value::Function(child) = value {
            walk(child, out);
        }
    }
}

/// Reads every bytecode section of `bundle`, records the opcodes seen and
/// returns the section kinds found.
fn read_bundle(label: &str, bundle: &[u8], seen: &mut BTreeSet<u8>) -> Vec<(SectionKind, Header)> {
    let sections = primjs::bundle_bytecode_sections(bundle)
        .unwrap_or_else(|error| panic!("{label}: sections: {error}"));
    let mut kinds = Vec::new();
    for section in sections {
        let (packed, program) = primjs::read_payload(section.bytes)
            .unwrap_or_else(|error| panic!("{label} {}: {error}", section.name));
        assert_eq!(
            packed.is_some(),
            section.kind == SectionKind::JsBytecode,
            "{label}"
        );
        assert!(!primjs::disassemble(&program).is_empty());
        let mut functions = Vec::new();
        walk(&program.root, &mut functions);
        for function in functions {
            for instruction in &function.instructions {
                seen.insert(instruction.opcode.number());
            }
        }
        kinds.push((section.kind, program.header));
    }
    kinds
}

#[test]
fn every_corpus_program_and_fixture_reads() {
    let mut seen = BTreeSet::new();
    let mut inputs = 0usize;
    for program in bytecode::PROGRAMS {
        for variant in bytecode::Variant::ALL {
            let label = format!("{} {}", program.name, variant.name());
            let kinds = read_bundle(&label, program.bundle(variant), &mut seen);
            let root = kinds
                .iter()
                .filter(|(kind, _)| *kind == SectionKind::RootLepus)
                .count();
            let background = kinds
                .iter()
                .filter(|(kind, _)| *kind == SectionKind::JsBytecode)
                .count();
            assert_eq!((root, background), (1, 1), "{label}");
            inputs += 2;
            // Header forms per variant, as the corpus documents them.
            for (kind, header) in kinds {
                let flags = header.flags();
                let expected = match (variant, kind) {
                    (
                        bytecode::Variant::Sdk2_13 | bytecode::Variant::InlineDebug,
                        SectionKind::RootLepus,
                    )
                    | (bytecode::Variant::Sdk2_13, _) => (1, false, false),
                    (bytecode::Variant::Sdk4_1, SectionKind::RootLepus) => (9, true, true),
                    _ => (9, true, false),
                };
                assert_eq!(
                    (
                        header.version_byte(),
                        flags.external_debug_info,
                        flags.vardefs_stripped
                    ),
                    expected,
                    "{label} {kind:?}"
                );
            }
        }
    }
    assert_eq!(inputs, bytecode::PROGRAMS.len() * 4 * 2);
    for fixture in bytecode::FIXTURES {
        read_bundle(fixture.name, fixture.page, &mut seen);
        let kinds = read_bundle(fixture.name, fixture.js_bytecode_page, &mut seen);
        assert!(
            kinds
                .iter()
                .any(|(kind, _)| *kind == SectionKind::JsBytecode),
            "{}",
            fixture.name
        );
    }

    let unseen: Vec<&str> = ALL_OPCODES
        .iter()
        .filter(|opcode| **opcode != Opcode::Invalid && !seen.contains(&opcode.number()))
        .map(|opcode| opcode.name())
        .collect();
    eprintln!(
        "{inputs} corpus inputs and {} fixtures read; {} opcodes never occur: {}",
        bytecode::FIXTURES.len(),
        unseen.len(),
        unseen.join(" ")
    );
}
